        *out = static_cast<uint64_t>(res);
        return static_cast<uint8_t>(res >> 64);
#else
        uint64_t sum = a + carry_in;
        uint8_t c1 = static_cast<uint8_t>(sum < a);
        sum += b;
        uint8_t c2 = static_cast<uint8_t>(sum < b);
        *out = sum;
        return c1 | c2;
#endif
